            "\u0000\ufe59\u0000\ufe5a\u0001\u0000\ufe5a\u0000\ufe59\u0002\u0000\ufe5b\u0000\ufe5c\u0001\u0000\ufe5c\u0000\ufe5b\u0002\u0000\ufe5d\u0000\ufe5e\u0001\u0000\ufe5e\u0000\ufe5d\u0002\u0000\uff08\u0000\uff09\u0001\u0000\uff09\u0000\uff08\u0002\u0000\uff3b\u0000\uff3d\u0001\u0000\uff3d\u0000\uff3b\u0002\u0000\uff5b\u0000\uff5d\u0001\u0000\uff5d\u0000\uff5b\u0002\u0000\uff5f\u0000\uff60\u0001\u0000\uff60\u0000\uff5f\u0002\u0000\uff62\u0000\uff63\u0001\u0000\uff63\u0000\uff62\u0002";
        internal static int Bracket(int cp, bool kind = false) {
            int lo = 0, hi = Brackets.Length / 5 - 1;
            while (lo <= hi) { int m = (lo + hi) / 2, p = m * 5, key = Scalar(Brackets, p);
                if (cp < key) hi = m - 1; else if (cp > key) lo = m + 1;
                else return kind ? Brackets[p + 4] : Scalar(Brackets, p + 2); }
            return 0;
        }
    }
